RUNTIME_DASHBOARD = """<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>DGX MoA Runtime</title><style>
:root{color-scheme:dark;--bg:#060914;--panel:#0e1528;--card:#121c33;--line:#2a3754;--text:#eef3ff;--muted:#93a0b8;--accent:#8ba8ff;--accent2:#b98cff;--ok:#53ddb1;--warn:#ffca67;--bad:#ff7892;--shadow:0 18px 48px #0007}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 12% 0,#352668 0,transparent 32%),radial-gradient(circle at 88% 4%,#143f63 0,transparent 26%),var(--bg);color:var(--text);font:14px/1.45 Inter,ui-sans-serif,system-ui,sans-serif}button,input,select{font:inherit}button,input{border:1px solid var(--line);border-radius:10px;padding:9px 12px;background:#0a1020;color:var(--text)}button{cursor:pointer}button:hover,button:focus-visible{border-color:var(--accent);outline:none}.primary{background:linear-gradient(135deg,#586eea,#7d4fbd);border:0;font-weight:700}.muted{color:var(--muted)}.ok{color:var(--ok)}.warn{color:var(--warn)}.bad{color:var(--bad)}.hidden,[hidden]{display:none!important}main{max-width:1600px;margin:auto;padding:24px}#login{max-width:620px;margin:12vh auto;padding:28px}.panel{border:1px solid var(--line);border-radius:18px;background:#0e1528e8;box-shadow:var(--shadow)}header{display:flex;align-items:center;justify-content:space-between;gap:16px}.brand{display:flex;align-items:center;gap:12px}.mark{width:42px;height:42px;border-radius:13px;background:linear-gradient(135deg,var(--accent),var(--accent2));display:grid;place-items:center;color:#080b16;font-weight:900}.brand h1{font-size:22px;margin:0}.header-actions{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.pill{border:1px solid var(--line);border-radius:999px;padding:6px 10px;background:#ffffff08}.nav{display:flex;gap:7px;margin:20px 0;overflow:auto;padding-bottom:2px}.nav button{white-space:nowrap;background:#0c1325}.nav button[aria-current="page"]{border-color:var(--accent);background:#26345c}.kpis{display:grid;grid-template-columns:repeat(6,minmax(120px,1fr));gap:10px;margin-bottom:14px}.kpi{padding:14px}.kpi span{display:block;color:var(--muted);font-size:12px}.kpi strong{display:block;font-size:23px;margin-top:4px}.toolbar{display:flex;justify-content:space-between;gap:10px;align-items:center;padding:14px 16px;border-bottom:1px solid var(--line);flex-wrap:wrap}.toolbar h2{font-size:16px;margin:0}.toolbar-group{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.content{padding:16px}.live-grid{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(300px,.8fr);gap:14px}.lanes{display:grid;grid-template-columns:repeat(4,minmax(150px,1fr));gap:8px;overflow:auto}.lane{min-height:180px;border:1px solid var(--line);border-radius:13px;padding:9px;background:#ffffff04}.lane h3{font-size:11px;letter-spacing:.09em;color:var(--muted);margin:2px 0 9px}.node{margin:7px 0;padding:9px;border-left:3px solid var(--accent);border-radius:6px;background:#ffffff08;word-break:break-word;font-size:12px}.node[data-state="SUCCEEDED"],.node[data-state="completed"]{border-color:var(--ok)}.node[data-state="FAILED"],.node[data-state="failed"]{border-color:var(--bad)}.node small{display:block;color:var(--muted);margin-top:3px}.timeline{max-height:66vh;overflow:auto}.event{display:grid;grid-template-columns:116px minmax(145px,.55fr) minmax(0,1.5fr);gap:10px;padding:9px 4px;border-bottom:1px solid var(--line);align-items:start}.event code{white-space:pre-wrap;word-break:break-word;color:#c8d4eb}.event .kind{font-weight:650}.empty{padding:42px 14px;text-align:center;color:var(--muted)}.notice{margin-bottom:12px;padding:11px 14px;border:1px solid var(--line);border-radius:12px;background:#ffffff06}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px 10px;border-bottom:1px solid var(--line);vertical-align:top}th{position:sticky;top:0;background:var(--panel);color:var(--muted);font-size:11px;letter-spacing:.06em;text-transform:uppercase}tbody tr[data-action]{cursor:pointer}tbody tr[data-action]:hover{background:#ffffff07}.status{display:inline-block;border-radius:999px;padding:3px 8px;background:#ffffff0b}.status.completed,.status.SUCCEEDED{color:var(--ok)}.status.failed,.status.FAILED,.status.blocked{color:var(--bad)}.split{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.section{border:1px solid var(--line);border-radius:14px;padding:14px;background:#ffffff04}.section h3{margin:0 0 12px;font-size:14px}.bars{display:grid;gap:9px}.bar-label{display:flex;justify-content:space-between;gap:10px}.bar-track{height:7px;background:#ffffff0b;border-radius:999px;overflow:hidden}.bar-fill{height:100%;background:linear-gradient(90deg,var(--accent),var(--accent2));border-radius:inherit}.kv{display:grid;grid-template-columns:minmax(120px,.35fr) minmax(0,1fr);gap:0}.kv>*{padding:8px;border-bottom:1px solid var(--line)}pre{margin:0;white-space:pre-wrap;word-break:break-word;color:#cbd7ed;font:12px/1.55 ui-monospace,SFMono-Regular,Consolas,monospace}.audit-form{display:grid;grid-template-columns:1fr 2fr auto;gap:8px}dialog{width:min(1100px,calc(100vw - 28px));height:min(88vh,900px);padding:0;border:1px solid var(--line);border-radius:18px;background:var(--panel);color:var(--text);box-shadow:var(--shadow)}dialog::backdrop{background:#02040bcc;backdrop-filter:blur(5px)}.dialog-head{position:sticky;top:0;z-index:2;display:flex;justify-content:space-between;gap:10px;align-items:center;padding:16px;border-bottom:1px solid var(--line);background:var(--panel)}.dialog-head h2{margin:0;font-size:17px}.tabs{display:flex;gap:6px;overflow:auto;padding:12px 16px 0}.tabs button[aria-selected="true"]{border-color:var(--accent);background:#26345c}.inspector-body{padding:16px;overflow:auto;height:calc(100% - 116px)}@media(max-width:1100px){.kpis{grid-template-columns:repeat(3,1fr)}.live-grid{grid-template-columns:1fr}.lanes{grid-template-columns:repeat(4,190px)}}@media(max-width:720px){main{padding:12px}.kpis{grid-template-columns:repeat(2,1fr)}.split{grid-template-columns:1fr}.event{grid-template-columns:1fr}.audit-form{grid-template-columns:1fr}header{align-items:flex-start}.header-actions{justify-content:flex-end}.brand .muted{display:none}}
.live-grid .event{grid-template-columns:1fr}
</style></head><body><main>
<section id="login" class="panel"><div class="brand"><div class="mark">M</div><div><h1>DGX MoA Runtime</h1><span class="muted">ExecutionGraph observability</span></div></div><p class="muted">API key는 서버에서 1일 HttpOnly session으로 교환되며 브라우저 저장소에 보관되지 않습니다.</p><form id="login-form"><label for="token">API key</label><div class="toolbar-group"><input id="token" type="password" autocomplete="off" size="44" required><button class="primary">Dashboard 연결</button></div></form><p id="login-state" class="bad" role="alert"></p></section>
<div id="app" hidden><header><div class="brand"><div class="mark">M</div><div><h1>Dynamic MoA</h1><span id="identity" class="muted"></span></div></div><div class="header-actions"><span id="updated" class="muted"></span><span id="socket" class="pill muted">연결 중</span><button id="refresh">새로고침</button><button id="logout">로그아웃</button></div></header>
<nav class="nav" aria-label="Dashboard 메뉴"><button data-view="live">LIVE</button><button data-view="requests">REQUESTS</button><button data-view="models">MODELS</button><button data-view="system">SYSTEM</button><button data-view="incidents">INCIDENTS</button><button data-view="evaluation">EVALUATION</button><button data-view="audit">AUDIT</button></nav>
<section id="kpis" class="kpis" aria-label="핵심 지표"></section><p id="notice" class="notice" hidden role="status"></p><section class="panel"><div id="view-toolbar" class="toolbar"></div><div id="content" class="content"></div></section></div>
</main><dialog id="inspector"><div class="dialog-head"><div><h2 id="inspector-title">Inspector</h2><span id="inspector-subtitle" class="muted"></span></div><button id="inspector-close" aria-label="Inspector 닫기">닫기</button></div><div id="inspector-tabs" class="tabs" role="tablist"></div><div id="inspector-body" class="inspector-body"></div></dialog>
<script>
const $=id=>document.getElementById(id),roles=["Reasoner","Planner","Frontier A","Executor","Tools","Reviewer","Judge","Frontier B"],graphLanes=["Static Skeleton",...roles],tabs=["SUMMARY","PROMPT","LIVE","OUTPUT","EVIDENCE","EXECUTION","LOGS"];
const state={me:null,view:"live",requests:null,snapshot:null,telemetry:null,events:[],detail:null,detailTab:"SUMMARY",paused:false,filter:"",lastSeq:0,synced:false};let socket,retry=1000,reconnect=true,scheduled=false,detailRefresh;
const node=(tag,className,text)=>{const item=document.createElement(tag);if(className)item.className=className;if(text!=null)item.textContent=String(text);return item};
const clear=item=>item.replaceChildren();const compact=value=>value==null||value===""?"—":String(value);const number=value=>new Intl.NumberFormat("ko-KR").format(Number(value||0));
const time=value=>{if(!value)return"—";const date=new Date(value);return Number.isNaN(date.valueOf())?String(value):date.toLocaleString("ko-KR")};
const safeJson=value=>JSON.stringify(value??{},null,2);const api=async(path,options={})=>{const response=await fetch(path,{...options,headers:{"Content-Type":"application/json",...(options.headers||{})}});if(!response.ok){let body={};try{body=await response.json()}catch{}throw new Error(body.error?.message||body.detail||response.statusText)}return response.status===204?null:response.json()};
const setNotice=(message,bad=false)=>{const item=$("notice");item.hidden=!message;item.textContent=message||"";item.className="notice "+(bad?"bad":"")};
const scheduleRender=()=>{if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{scheduled=false;render()})};
const usage=()=>state.requests?.usage||{};const rows=(name)=>Array.isArray(usage()[name])?usage()[name]:[];
const ownSummary=()=>{const values=rows("summary");if(state.me?.operator)return values.reduce((sum,item)=>({requests:sum.requests+item.requests,total_tokens:sum.total_tokens+item.total_tokens,completed:sum.completed+item.completed,failed:sum.failed+item.failed}),{requests:0,total_tokens:0,completed:0,failed:0});return values.find(item=>item.name===state.me?.api_key_id)||values[0]||{requests:(state.requests?.requests||[]).length,total_tokens:0,completed:0,failed:0}};
const graphStats=()=>{const data=state.snapshot?.execution_graphs;if(!data)return{graphs:0,active:0,pending:0,nodes:0,attempts:0};if(!Array.isArray(data))return{graphs:data.graph_count||0,active:data.active_nodes||0,pending:data.pending_nodes||0,nodes:0,attempts:0};return data.reduce((sum,item)=>({graphs:sum.graphs+1,active:sum.active+(item.checkpoint?.active_node_ids?.length||0),pending:sum.pending+(item.checkpoint?.pending_node_ids?.length||0),nodes:sum.nodes+(item.graph?.nodes?.length||0),attempts:sum.attempts+(item.attempts?.length||0)}),{graphs:0,active:0,pending:0,nodes:0,attempts:0})};
const metric=(label,value,tone="")=>{const box=node("div","kpi panel"),caption=node("span","",label),strong=node("strong",tone,value);box.append(caption,strong);return box};
const renderKpis=()=>{const summary=ownSummary(),graphs=graphStats(),fallback=rows("fallback_summary").reduce((sum,item)=>sum+item.fallbacks,0);$("kpis").replaceChildren(metric("요청",number(summary.requests)),metric("완료",number(summary.completed),"ok"),metric("실패",number(summary.failed),summary.failed?"bad":""),metric("토큰",number(summary.total_tokens)),metric("ExecutionGraph",number(graphs.graphs)),metric("Fallback",number(fallback),fallback?"warn":""))};
const toolbar=(title,...controls)=>{const box=$("view-toolbar");clear(box);box.append(node("h2","",title));const group=node("div","toolbar-group");controls.filter(Boolean).forEach(item=>group.append(item));box.append(group)};
const button=(label,action,className="")=>{const item=node("button",className,label);item.type="button";item.onclick=action;return item};
const search=placeholder=>{const item=node("input");item.type="search";item.placeholder=placeholder;item.value=state.filter;item.oninput=event=>{state.filter=event.target.value.toLowerCase();scheduleRender()};return item};
const statusBadge=value=>node("span","status "+String(value||""),compact(value));
const makeTable=(headers,data,onSelect)=>{if(!data.length)return node("div","empty","표시할 데이터가 없습니다.");const wrap=node("div","table-wrap"),table=node("table"),head=node("thead"),headRow=node("tr");headers.forEach(([label])=>headRow.append(node("th","",label)));head.append(headRow);const body=node("tbody");data.forEach(row=>{const tr=node("tr");if(onSelect){tr.dataset.action="open";tr.tabIndex=0;tr.onclick=()=>onSelect(row);tr.onkeydown=event=>{if(event.key==="Enter")onSelect(row)}}headers.forEach(([,read])=>{const cell=node("td"),value=read(row);cell.append(value instanceof Node?value:document.createTextNode(compact(value)));tr.append(cell)});body.append(tr)});table.append(head,body);wrap.append(table);return wrap};
const eventMatches=(event,terms)=>terms.some(term=>(event.event_type||"").toLowerCase().includes(term));
const filteredEvents=terms=>state.events.filter(event=>(!terms||eventMatches(event,terms))&&(!state.filter||safeJson(event).toLowerCase().includes(state.filter)));
const eventList=events=>{if(!events.length)return node("div","empty","아직 수집된 이벤트가 없습니다.");const list=node("div","timeline");events.slice(0,300).forEach(event=>{const row=node("div","event"),stamp=node("span","muted",time(event.created_at)),kind=node("span","kind",event.event_type||event.type),payload=node("code","",safeJson(event.payload||{}));row.append(stamp,kind,payload);list.append(row)});return list};
const graphRole=graphNode=>{const type=(graphNode.node_type||"").toUpperCase();if(type==="FRONTIER_B")return"Frontier B";if(type==="FRONTIER_A")return"Frontier A";if(["TOOL","TEST"].includes(type))return"Tools";return roles.find(role=>type.includes(role.toUpperCase().split(" ")[0]))||"Executor"};
const graphLane=graphNode=>["CLASSIFY","JOIN","POLICY_GATE","HUMAN_APPROVAL","EXECUTOR_SELECT","CHECKPOINT","FINALIZE"].includes((graphNode.node_type||"").toUpperCase())?"Static Skeleton":graphRole(graphNode);
const graphCard=(graph,item,attempts)=>{const card=node("div","node"),attempt=[...attempts].reverse().find(entry=>entry.node_id===item.node_id),edges=(graph.edges||[]).filter(edge=>edge.from_node===item.node_id);card.dataset.nodeId=item.node_id;card.dataset.state=attempt?.state||"";card.tabIndex=0;card.setAttribute("role","button");card.onclick=()=>openGraphNode(graph,item,attempt,edges);card.onkeydown=event=>{if(event.key==="Enter")card.click()};card.append(node("strong","",item.node_id+" · "+item.node_type));card.append(node("small","",[attempt?.state,item.provider||attempt?.provider,item.parallel_group_id,attempt?.latency_ms==null?null:attempt.latency_ms+"ms"].filter(Boolean).join(" · ")));if(edges.length)card.append(node("small","",edges.map(edge=>edge.edge_type+" → "+edge.to_node).join(", ")));return card};
const workflow=()=>{const canvas=node("div"),topology=state.snapshot?.topology?.graph||{},contract=node("div","notice",`Static Graph Skeleton → runtime-created request subgraph · ${compact(topology.mode)} · runtime mutation ${topology.runtime_mutation===false?"disabled":"unknown"}`),lanes=node("div","lanes"),byRole={};graphLanes.forEach(role=>{const lane=node("section","lane"),title=node("h3","",role.toUpperCase());lane.append(title);byRole[role]=lane;lanes.append(lane)});const snapshots=Array.isArray(state.snapshot?.execution_graphs)?state.snapshot.execution_graphs:[];snapshots.forEach(item=>(item.graph?.nodes||[]).forEach(graphNode=>byRole[graphLane(graphNode)].append(graphCard(item.graph,graphNode,item.attempts||[]))));if(!snapshots.length)byRole.Executor.append(node("div","empty","Graph 없음"));canvas.append(contract,lanes);return canvas};
const liveView=()=>{toolbar("실시간 ExecutionGraph",search("이벤트 검색"),button(state.paused?"재개":"일시정지",()=>{state.paused=!state.paused;scheduleRender()}));const grid=node("div","live-grid"),left=node("section","section"),right=node("section","section");left.append(node("h3","","Workflow canvas"),workflow());right.append(node("h3","","Event timeline"),eventList(filteredEvents()));grid.append(left,right);return grid};
const requestRows=()=>((state.requests?.requests)||[]).filter(item=>!state.filter||safeJson(item).toLowerCase().includes(state.filter));
const requestsView=()=>{toolbar("요청",search("ID, 작업, 상태 검색"),button("REST 갱신",refreshData));if(state.requests?.scope!=="private"){const note=node("div","notice","Operator 기본 화면은 key별 aggregate만 표시합니다. Cross-key 상세는 AUDIT에서 사유를 기록한 뒤 조회하세요.");return nodeGroup(note,summaryTable())}return makeTable([["Updated",item=>time(item.updated_at)],["Session",item=>item.session_id],["Class",item=>item.request_class],["Phase",item=>item.phase],["Status",item=>statusBadge(item.client_response_status||item.final_status||"running")],["Objective",item=>item.objective]],requestRows(),item=>openRequest(item.session_id))};
const summaryTable=()=>makeTable([["Key",item=>item.name],["Requests",item=>number(item.requests)],["Completed",item=>number(item.completed)],["Failed",item=>number(item.failed)],["Tokens",item=>number(item.total_tokens)],["Last used",item=>time(item.last_used_at)]],rows("summary"));
const nodeGroup=(...items)=>{const group=node("div");items.forEach(item=>group.append(item));return group};
const bars=(data,label,value)=>{if(!data.length)return node("div","empty","집계 데이터가 없습니다.");const max=Math.max(...data.map(value),1),box=node("div","bars");data.slice(0,12).forEach(item=>{const row=node("div"),head=node("div","bar-label");head.append(node("span","",label(item)),node("strong","",number(value(item))));const track=node("div","bar-track"),fill=node("div","bar-fill");fill.style.width=Math.max(2,value(item)/max*100)+"%";track.append(fill);row.append(head,track);box.append(row)});return box};
const modelsView=()=>{toolbar("가용 MoA 모델·Provider",search("역할, 모델, provider, 상태 검색"));const topology=(state.snapshot?.topology?.roles||[]).filter(item=>!state.filter||safeJson(item).toLowerCase().includes(state.filter)),availability=makeTable([["Role",item=>item.role],["Model",item=>item.model],["Provider",item=>item.provider],["Enabled",item=>item.enabled?"yes":"no"],["Availability",item=>item.available===true?statusBadge("ready"):item.available===false?statusBadge("unavailable"):statusBadge("unprobed")],["Evidence",item=>item.availability_basis]],topology),models=rows("models").filter(item=>!state.filter||safeJson(item).toLowerCase().includes(state.filter)),fallbacks=rows("fallbacks").filter(item=>!state.filter||safeJson(item).toLowerCase().includes(state.filter));const grid=node("div","split"),usageBox=node("section","section"),fallbackBox=node("section","section");usageBox.append(node("h3","","Invocation / tokens"),bars(models,item=>[item.role,item.model,item.provider].filter(Boolean).join(" · "),item=>item.total_tokens));fallbackBox.append(node("h3","","Fallback family"),bars(fallbacks,item=>[item.role,item.reason].filter(Boolean).join(" · "),item=>item.invocations));grid.append(usageBox,fallbackBox);const daily=makeTable([["Day",item=>item.day],["Model",item=>item.model],["Calls",item=>number(item.invocations)],["Prompt",item=>number(item.prompt_tokens)],["Cached",item=>item.cached_tokens==null?"미측정":number(item.cached_tokens)],["Completion",item=>number(item.completion_tokens)],["Total",item=>number(item.total_tokens)]],rows("daily_models"));return nodeGroup(availability,node("br"),grid,node("br"),daily)};
const systemView=()=>{toolbar("시스템·Runtime",search("memory, GPU, KV, health 검색"));const stats=graphStats(),facts=[['Scope',state.me?.operator?'operator aggregate':'private owner'],['WebSocket',$("socket").textContent],['Graphs',stats.graphs],['Nodes',stats.nodes],['Attempts',stats.attempts],['Active nodes',stats.active],['Pending nodes',stats.pending],['Replay cursor',state.lastSeq],['Buffered live events',state.events.length]],kv=node("div","kv");facts.forEach(([key,value])=>kv.append(node("strong","",key),node("span","",value)));const telemetry=filteredEvents(["telemetry","memory","gpu","kv","swap","power","health","lifecycle","model_state"]);const grid=node("div","split"),overview=node("section","section"),feed=node("section","section");overview.append(node("h3","","Runtime summary"),kv);feed.append(node("h3","","Measured telemetry events"),eventList(telemetry));grid.append(overview,feed);return nodeGroup(grid,node("br"),detailSection("GB10 / ssh mathcat telemetry",state.telemetry||{status:"unavailable"}))};
const incidentsView=()=>{toolbar("장애·Recovery",search("failure class, provider, reason 검색"));const terms=["fail","error","incident","retry","cancel","timeout","oom","degrad","unavailable","recovery"],events=filteredEvents(terms),failed=requestRows().filter(item=>["failed","blocked","degraded","cancelled"].includes(item.final_status));const grid=node("div","split"),requests=node("section","section"),feed=node("section","section");requests.append(node("h3","","Affected requests"),makeTable([["Updated",item=>time(item.updated_at)],["Session",item=>item.session_id],["Status",item=>statusBadge(item.final_status)],["Objective",item=>item.objective]],failed,item=>openRequest(item.session_id)));feed.append(node("h3","","Failure / recovery timeline"),eventList(events));grid.append(requests,feed);return grid};
const evaluationView=()=>{toolbar("검증·Review",search("review, judge, test, evidence 검색"));const terms=["review","judge","test","validation","evidence","approval","completion","correction"],events=filteredEvents(terms);const grid=node("div","split"),quality=node("section","section"),feed=node("section","section");quality.append(node("h3","","Outcome summary"),summaryTable());feed.append(node("h3","","Evaluation timeline"),eventList(events));grid.append(quality,feed);return grid};
const auditView=()=>{toolbar("감사·Privacy boundary");const security=node("section","section"),kv=node("div","kv"),facts=[['Identity',state.me?.api_key_id],['Scope',state.me?.operator?'operator aggregate':'private owner'],['Session','HttpOnly · SameSite=Strict · 1 day'],['WebSocket','same-origin + cookie authentication'],['Dynamic content','textContent only'],['Cross-key raw view',state.me?.operator?'audited reason required':'not permitted']];facts.forEach(([key,value])=>kv.append(node("strong","",key),node("span","",value)));security.append(node("h3","","Effective access contract"),kv);if(!state.me?.operator)return security;const raw=node("section","section"),form=node("form","audit-form"),session=node("input"),reason=node("input"),submit=node("button","primary","감사 조회");session.placeholder="target session ID";session.required=true;reason.placeholder="8–256자 운영 사유";reason.minLength=8;reason.maxLength=256;reason.required=true;form.append(session,reason,submit);form.onsubmit=async event=>{event.preventDefault();await openRequest(session.value.trim(),reason.value.trim())};raw.append(node("h3","","Audited cross-key request inspector"),form,node("p","muted","조회 사유는 redaction 후 dashboard-audit event로 영구 기록됩니다."));const grid=node("div","split");grid.append(security,raw);return grid};
const views={live:liveView,requests:requestsView,models:modelsView,system:systemView,incidents:incidentsView,evaluation:evaluationView,audit:auditView};
function render(){if(!state.me)return;renderKpis();document.querySelectorAll(".nav button").forEach(item=>item.setAttribute("aria-current",item.dataset.view===state.view?"page":"false"));const content=$("content");clear(content);content.append(views[state.view]())}
const detailEvents=terms=>(state.detail?.events||[]).filter(event=>!terms||eventMatches(event,terms));
const detailSection=(title,value)=>{const box=node("section","section"),pre=node("pre","",typeof value==="string"?value:safeJson(value));box.append(node("h3","",title),pre);return box};
function openGraphNode(graph,item,attempt,edges){$("inspector-title").textContent="ExecutionGraph Node";$("inspector-subtitle").textContent=graph.graph_id+" · "+item.node_id;$("inspector-tabs").replaceChildren();$("inspector-body").replaceChildren(detailSection("Static skeleton / request subgraph",{template_id:graph.template_id,origin:graphLane(item)==="Static Skeleton"?"static_skeleton":"runtime_created_request_subgraph",node:item,latest_attempt:attempt||null,outgoing_edges:edges}));$("inspector").showModal()}
const inspectorContent=tab=>{const detail=state.detail||{},session=detail.state||{};if(tab==="SUMMARY")return detailSection("Request summary",{session_id:session.session_id,task_id:session.task_id,runtime_mode:session.runtime_mode,request_class:session.request_class,route:session.route,phase:session.phase,client_response_status:session.client_response_status,final_status:session.final_status,review_status:session.review_status,judge_status:session.judge_status,derived_confidence:session.derived_confidence,timings_ms:session.timings_ms,created_at:session.created_at,updated_at:session.updated_at});if(tab==="PROMPT")return detailSection("Redacted prompt / policy",{objective:session.objective,resolved_objective:session.resolved_objective,plan:session.plan,acceptance_criteria:session.acceptance_criteria,prompt_versions:session.prompt_versions,policy_decisions:session.policy_decisions});if(tab==="LIVE")return nodeGroup(detailSection("Current client-visible draft",session.current_draft||""),eventList(detailEvents(["stream","delta","output","assistant","progress"])));if(tab==="OUTPUT")return detailSection("Client-visible result",{current_draft:session.current_draft,final_output:session.final_output,client_response_status:session.client_response_status,final_status:session.final_status,finish_reasons:session.finish_reasons,completed_steps:session.completed_steps,output_events:detailEvents(["output","assistant","stream_finished","completed"])});if(tab==="EVIDENCE")return detailSection("Runtime-owned canonical evidence",{canonical_snapshot:{id:session.canonical_evidence_snapshot_id,hash:session.canonical_evidence_snapshot_hash},role_context_projections:session.role_context_projections,completion_evidence:session.completion_evidence,evidence_graph:{nodes:session.evidence_nodes,edges:session.evidence_edges},independent_judgments:{reviewer:(session.agent_artifacts||[]).filter(item=>item.role==="reviewer"),judge:session.judge_verdict,frontier:(session.agent_artifacts||[]).filter(item=>item.role==="frontier"),evaluations:session.evaluations},implementation_evidence:session.implementation_evidence,failures:session.failures,tool_results:session.tool_results,tool_executions:session.tool_executions});if(tab==="EXECUTION")return detailSection("ExecutionGraph",detail.execution_graph||{status:"not available"});return eventList(detail.events||[])};
const selectInspectorTab=tab=>{state.detailTab=tab;document.querySelectorAll("#inspector-tabs button").forEach(item=>item.setAttribute("aria-selected",item.textContent===tab?"true":"false"));const body=$("inspector-body");clear(body);body.append(inspectorContent(tab))};
async function openRequest(sessionId,reason){try{setNotice("");const options=reason?{method:"POST",body:JSON.stringify({reason})}:{};state.detail=await api("/v1/dashboard/requests/"+encodeURIComponent(sessionId),options);$("inspector-title").textContent="Request Inspector";$("inspector-subtitle").textContent=sessionId;const tabbar=$("inspector-tabs");clear(tabbar);tabs.forEach(tab=>{const item=button(tab,()=>selectInspectorTab(tab));item.setAttribute("role","tab");tabbar.append(item)});selectInspectorTab("SUMMARY");$("inspector").showModal()}catch(error){setNotice(error.message,true)}}
const absorbSnapshot=()=>{if(!Array.isArray(state.snapshot?.execution_graphs))return;state.snapshot.execution_graphs.forEach(item=>{const graph=item.graph||{};state.events.push({type:"execution_graph",event_type:"graph_saved",created_at:graph.created_at,graph_id:graph.graph_id,payload:graph});(item.attempts||[]).forEach(attempt=>state.events.push({type:"execution_graph",event_type:"node_attempt",created_at:attempt.ended_at||attempt.started_at,graph_id:graph.graph_id,payload:attempt}));if(item.checkpoint)state.events.push({type:"execution_graph",event_type:"graph_checkpoint",created_at:item.checkpoint.created_at,graph_id:graph.graph_id,payload:item.checkpoint})});state.events.sort((a,b)=>new Date(b.created_at||0)-new Date(a.created_at||0));state.events=state.events.slice(0,500)};
const applyGraphEvent=event=>{const graphs=state.snapshot?.execution_graphs;if(!Array.isArray(graphs)||event.type!=="execution_graph")return;let item=graphs.find(entry=>entry.graph?.graph_id===event.graph_id);if(event.event_type==="graph_saved"){if(!item)graphs.unshift({graph:event.payload,attempts:[],checkpoint:null});return}if(!item)return;if(event.event_type==="node_attempt"){const index=(item.attempts||[]).findIndex(attempt=>attempt.attempt_id===event.payload?.attempt_id);if(index<0)(item.attempts||(item.attempts=[])).push(event.payload);else item.attempts[index]=event.payload}else if(event.event_type==="graph_checkpoint")item.checkpoint=event.payload};
async function refreshData(){try{setNotice("");const [requests,snapshot,telemetry]=await Promise.all([api("/v1/dashboard/requests"),api("/v1/dashboard/snapshot"),api("/v1/dashboard/runtime")]);state.requests=requests;state.snapshot=snapshot;state.telemetry=telemetry;state.events=[];absorbSnapshot();$("updated").textContent="갱신 "+new Date().toLocaleTimeString("ko-KR");render()}catch(error){setNotice(error.message,true)}}
const refreshOpenDetail=sessionId=>{if(!state.detail||state.detail.state?.session_id!==sessionId||state.me?.operator)return;clearTimeout(detailRefresh);detailRefresh=setTimeout(async()=>{try{state.detail=await api("/v1/dashboard/requests/"+encodeURIComponent(sessionId));selectInspectorTab(state.detailTab)}catch(error){setNotice(error.message,true)}},150)};
const connect=()=>{if(!reconnect)return;const replay=state.synced?"?last_seq="+state.lastSeq:"";socket=new WebSocket((location.protocol==="https:"?"wss://":"ws://")+location.host+"/v1/dashboard/live"+replay);socket.onopen=()=>{$("socket").textContent="LIVE";$("socket").className="pill ok";retry=1000};socket.onmessage=async message=>{const event=JSON.parse(message.data);if(event.type==="heartbeat")return;if(event.type==="connected"){if(!state.synced){state.synced=true;state.lastSeq=event.current_seq||0;await refreshData();socket.close()}return}if(event.type==="RESYNC_REQUIRED"){state.synced=false;state.lastSeq=0;socket.close();return}if(event.gap){state.lastSeq=event.seq||state.lastSeq;await refreshData();return}if(event.seq)state.lastSeq=Math.max(state.lastSeq,event.seq);applyGraphEvent(event);state.events.unshift(event);state.events=state.events.slice(0,500);if(event.session_id)refreshOpenDetail(event.session_id);if(!state.paused)scheduleRender()};socket.onclose=()=>{if(!reconnect)return;$("socket").textContent="재연결 중";$("socket").className="pill bad";setTimeout(connect,retry);retry=Math.min(retry*2,10000)};socket.onerror=()=>socket.close()};
async function load(){state.me=await api("/v1/dashboard/me");$("identity").textContent=state.me.api_key_id+(state.me.operator?" · operator aggregate":" · private scope");$("login").hidden=true;$("app").hidden=false;await refreshData();connect()}
$("login-form").onsubmit=async event=>{event.preventDefault();try{$("login-state").textContent="";await api("/v1/dashboard/session",{method:"POST",headers:{Authorization:"Bearer "+$("token").value}});$("token").value="";await load()}catch(error){$("login-state").textContent=error.message}};
$("logout").onclick=async()=>{reconnect=false;if(socket)socket.close();await api("/v1/dashboard/session",{method:"DELETE"});location.reload()};$("refresh").onclick=refreshData;$("inspector-close").onclick=()=>$("inspector").close();document.addEventListener("keydown",event=>{if(event.key==="Escape"&&$("inspector").open)$("inspector").close()});document.querySelectorAll(".nav button").forEach(item=>item.onclick=()=>{state.view=item.dataset.view;state.filter="";render()});
load().catch(()=>$("login").hidden=false);
</script></body></html>"""
